export const getUpdateGoalEndpointUrl = (id: string) => {
  return `/api/goals/${id}`;
};

/**
 * Changes the name, the target, the target date, or how much has been put aside. This is how progress is recorded: raise currentAmount as money is saved.
 * @summary Update a savings goal
 */
export const updateGoalEndpoint = async (
  id: string,
  updateGoalRequest: UpdateGoalRequest,
  options?: Parameters<typeof customFetch>[1],
): Promise<GoalResponse> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return customFetch<GoalResponse>(getUpdateGoalEndpointUrl(id), {
    ...options,
    method: "PUT",
    headers: { "Content-Type": "application/json", ...getHeaders(options?.headers) },
    body: JSON.stringify(updateGoalRequest),
  });
};

