export const getSetupEndpointUrl = () => {
  return `/api/setup`;
};

/**
 * Creates the administrator account on a fresh instance. It works exactly once: once an administrator exists the endpoint answers 409 for good. Rate limited to five attempts per five minutes per client.
 * @summary Provision the first administrator
 */
export const setupEndpoint = async (
  setupRequest: SetupRequest,
  options?: Parameters<typeof customFetch>[1],
): Promise<UserProfileResponse> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return customFetch<UserProfileResponse>(getSetupEndpointUrl(), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...getHeaders(options?.headers) },
    body: JSON.stringify(setupRequest),
  });
};

export const getSetupEndpointMutationKey = () => ["setupEndpoint"] as const;

export const getSetupEndpointMutationOptions = <
  TError = ProblemDetails | void,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof setupEndpoint>>,
    TError,
    SetupEndpointMutationVariables,
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof setupEndpoint>>,
  TError,
  SetupEndpointMutationVariables,
  TContext
> => {
  const mutationKey = getSetupEndpointMutationKey();
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation && "mutationKey" in options.mutation && options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof setupEndpoint>>,
    SetupEndpointMutationVariables
  > = (props) => {
    const { data } = props ?? {};

    return setupEndpoint(data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

