export const getUpdateUserRoleEndpointUrl = (id: string) => {
  return `/api/users/${id}/role`;
};

/**
 * Promotes a user to administrator or demotes them to member. You cannot demote yourself, and the last administrator cannot be demoted, so an instance is never left without one. Administrators only.
 * @summary Change a user role
 */
export const updateUserRoleEndpoint = async (
  id: string,
  updateUserRoleRequest: UpdateUserRoleRequest,
  options?: Parameters<typeof customFetch>[1],
): Promise<UserProfileResponse> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return customFetch<UserProfileResponse>(getUpdateUserRoleEndpointUrl(id), {
    ...options,
    method: "PUT",
    headers: { "Content-Type": "application/json", ...getHeaders(options?.headers) },
    body: JSON.stringify(updateUserRoleRequest),
  });
};

